# lib_osha_nov20 / cases.py - eval cases for the federal OSHA and state safety program chunks. Run: python3 cases.py -> cases.jsonl
# Each case: the fact a right answer must contain (must), the direct answer expected in the first 40 words (lead), and the chunk that holds it.
import json
NOGO = ["(?:^|[.!] )(it'?s|it is|that'?s) safe", "you can (go in|enter)"]
C = []
def add(pref, cat, q, where, kind, must, lead, chunks, mustnot=None, level='pipelayer', strict=None):
    n = sum(1 for c in C if c['id'].startswith(pref + '-')) + 1
    c = dict(id=f'{pref}-{n}', cat=cat, q=q, where=where, level=level, kind=kind, must=must, lead=lead if isinstance(lead, list) else [lead],
             mustnot=mustnot or [], chunks=chunks if isinstance(chunks, list) else [chunks])
    if kind == 'complex': c['complex'] = True
    if strict is not None: c['state_strict'] = strict
    C.append(c)
def F(cat, q, where, kind, must, lead, chunks, mustnot=None, level='pipelayer'):
    add('lib-us-osha', cat, q, where, kind, must, lead, chunks, mustnot, level)
def S(st, cat, q, where, kind, must, lead, chunks, mustnot=None, level='pipelayer'):
    add(f'lib-{st}-sp', cat, q, where, kind, must, lead, chunks, mustnot, level, True)
